sys_script.script:
// BR2: Set Assigned At + Auto-Transition New → Assigned
(function () {
    var assignedTo = current.getValue('assigned_to');
    var prevAssignedTo = previous ? previous.getValue('assigned_to') : '';
    // When assigned_to changes from empty to a value
    if (assignedTo && !prevAssignedTo) {
        var now = new GlideDateTime();
        current.setValue('assigned_at', now);
        // If state is New (1), move to Assigned (2)
        if (current.getValue('state') == '1') {
            current.setValue('state', '2');
        }
    }
})();
